import DOMPurify from 'isomorphic-dompurify';
const tags=['p','strong','em','sub','sup','table','caption','thead','tbody','tr','th','td','blockquote','ul','ol','li','span','math'];
export function sanitizeRichText(value:string){return DOMPurify.sanitize(value,{ALLOWED_TAGS:tags,ALLOWED_ATTR:['lang','scope','colspan','rowspan'],ALLOW_DATA_ATTR:false,ALLOW_ARIA_ATTR:false});}
/** MathML is generated by KaTeX with trust:false, then sanitized; no source HTML enters this path. */
export function sanitizeMath(value:string){return DOMPurify.sanitize(value,{USE_PROFILES:{html:true,mathMl:true},FORBID_TAGS:['script','iframe','object','embed','img','a','style'],FORBID_ATTR:['id','href','src','xlink:href'],ALLOW_DATA_ATTR:false});}
/** Preserve literal prose and inequalities; callers render this as a React text node, never as HTML. */
export function sanitizePlainText(value:string){const escaped=value.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');return DOMPurify.sanitize(escaped,{ALLOWED_TAGS:[],ALLOWED_ATTR:[],RETURN_DOM_FRAGMENT:true}).textContent??'';}
